// Filter emails that have a PDF attachment and mention invoice/bill in subject.
// Returns one item per PDF attachment so each is processed independently.

const items = $input.all();
const results = [];

const INVOICE_KEYWORDS = ['invoice', 'bill', 'receipt', 'tax invoice', 'proforma'];

for (const item of items) {
  const email = item.json;
  const subject = (email.subject || '').toLowerCase();
  const messageId = email.id || email.messageId || `uid-${Date.now()}-${Math.random().toString(36).slice(2)}`;
  const senderEmail = email.from?.address || email.from?.text || 'unknown@unknown.com';

  // Check subject keyword match
  const subjectMatch = INVOICE_KEYWORDS.some(kw => subject.includes(kw));

  // Find PDF attachments
  const attachments = Array.isArray(email.attachments) ? email.attachments : [];
  const pdfAttachments = attachments.filter(att => {
    const ct = (att.contentType || att.type || '').toLowerCase();
    const fn = (att.filename || att.name || '').toLowerCase();
    return ct.includes('pdf') || fn.endsWith('.pdf');
  });

  // Include if: subject matches invoice keywords OR has a PDF attachment
  if (!subjectMatch && pdfAttachments.length === 0) {
    console.log(`[vendor-invoice-imap] Skipping email "${email.subject}" — no invoice keyword and no PDF`);
    continue;
  }

  if (pdfAttachments.length === 0) {
    console.log(`[vendor-invoice-imap] Skipping email "${email.subject}" — invoice keyword found but no PDF attachment`);
    continue;
  }

  // Emit one item per PDF attachment
  for (const att of pdfAttachments) {
    results.push({
      json: {
        email_uid: email.uid || null,
        message_id: messageId,
        sender_email: senderEmail,
        subject: email.subject || '(no subject)',
        body: (email.text || email.html || '').substring(0, 2000),
        attachment_filename: att.filename || att.name || 'invoice.pdf',
        attachment_base64: att.content || att.data || null,
        attachment_content_type: att.contentType || att.type || 'application/pdf',
      }
    });
  }
}

console.log(`[vendor-invoice-imap] Emitting ${results.length} PDF attachments for ingestion`);
return results;

// Build a unique source email ID from the message-id + attachment filename.
// This is stored in vendor_bills.ai_source_email_id for idempotency.
const item = $input.first().json;

// Sanitize the message_id for use in storage paths
const rawId = item.message_id || `unknown-${Date.now()}`;
const safeEmailId = rawId
  .replace(/[<>]/g, '')
  .replace(/[^a-zA-Z0-9._@-]/g, '_')
  .substring(0, 120);

const safeFilename = (item.attachment_filename || 'invoice.pdf')
  .replace(/[^a-zA-Z0-9._-]/g, '_');

return [{
  json: {
    ...item,
    source_email_id: safeEmailId,
    safe_filename: safeFilename,
  }
}];

// Check ingest API response. On success, mark the email as read.
// On failure, log the error but do NOT mark as read (retry on next cron run).

const response = $input.first().json;
const success = response.success === true || response.bill_id != null;

console.log(`[vendor-invoice-imap] Ingest response:`, JSON.stringify(response));

if (!success) {
  console.error(`[vendor-invoice-imap] Extraction failed — leaving email unread for retry.`, {
    error: response.error,
    code: response.code,
    source_email_id: response.source_email_id || '(unknown)',
    vendor_name_extracted: response.vendor_name_extracted || '(unknown)',
  });
  // Return empty to stop this branch (email stays unread)
  return [];
}

console.log(`[vendor-invoice-imap] Success: bill_id=${response.bill_id}, vendor_matched=${response.vendor_matched}, confidence=${response.confidence_score}`);

// Pass through for the mark-as-read step
return [{ json: { ...response, _ingest_ok: true, email_uid: $('Build Ingest Payload').first().json.email_uid } }];

// Extraction failed — log and exit silently.
// The email remains unread and will be retried in 15 minutes.
console.log('[vendor-invoice-imap] Email left unread for retry (extraction failure).');
return [];

// No usable PDF base64 data — skip silently.
console.log('[vendor-invoice-imap] Skipping item — PDF base64 data is empty or null.');
return [];
